import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Função para calcular distância entre dois pontos (Haversine)
function distanciaEmKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Captura movimentos do mapa
function MapaEventos({ onBoundsChange }) {
  useMapEvents({
    moveend: (e) => {
      const bounds = e.target.getBounds();
      onBoundsChange(bounds);
    },
    zoomend: (e) => {
      const bounds = e.target.getBounds();
      onBoundsChange(bounds);
    },
  });
  return null;
}

function MapView() {
  const [revendas, setRevendas] = useState([]);
  const [filteredRevendas, setFilteredRevendas] = useState([]);
  const [meta, setMeta] = useState({ progresso: 0, ultimaAtualizacao: null });
  const [loading, setLoading] = useState(true);
  const [userPosition, setUserPosition] = useState(null);

  // Filtros
  const [ufs, setUfs] = useState([]);
  const [municipios, setMunicipios] = useState([]);
  const [selectedUf, setSelectedUf] = useState("");
  const [selectedMunicipio, setSelectedMunicipio] = useState("");
  const [cnpj, setCnpj] = useState("");

  // ⚠️ Ajusta para o IP da tua rede local
  const BACKEND_URL = "http://192.168.0.81:5000";

  // Localização do utilizador
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setUserPosition([pos.coords.latitude, pos.coords.longitude]);
        },
        () => {
          console.warn("📍 Permissão de localização negada.");
        }
      );
    }
  }, []);

  // Verifica progresso da atualização
  useEffect(() => {
    const interval = setInterval(() => {
      fetch(`${BACKEND_URL}/api/meta`)
        .then((res) => res.json())
        .then((data) => {
          setMeta(data);
          if (data.progresso === 100 && loading) {
            carregarRevendas(); // primeira carga
            setLoading(false);
          }
        });
    }, 5000);
    return () => clearInterval(interval);
  }, [loading]);

  // Função para buscar revendas no backend já filtradas
  async function carregarRevendas() {
    let url = `${BACKEND_URL}/api/revendas?`;
    if (selectedUf) url += `uf=${encodeURIComponent(selectedUf)}&`;
    if (selectedMunicipio) url += `municipio=${encodeURIComponent(selectedMunicipio)}&`;
    if (cnpj) url += `cnpj=${encodeURIComponent(cnpj)}&`;

    const res = await fetch(url);
    const dados = await res.json();
    setRevendas(dados);
    setFilteredRevendas(dados);

    // Atualiza lista de UFs e municípios
    const uniqueUfs = [...new Set(dados.map((r) => r.uf))].sort();
    setUfs(uniqueUfs);

    if (selectedUf) {
      const filteredMunicipios = [
        ...new Set(dados.filter((r) => r.uf === selectedUf).map((r) => r.municipio)),
      ].sort();
      setMunicipios(filteredMunicipios);
    }
  }

  // Recarrega quando filtros mudam
  useEffect(() => {
    if (meta.progresso === 100) {
      carregarRevendas();
    }
  }, [selectedUf, selectedMunicipio, cnpj, meta.progresso]);

  // Atualiza lista visível ao mover/zoom
  function handleBoundsChange(bounds) {
    if (!bounds) return;
    const center = bounds.getCenter();
    const results = revendas.filter((r) => {
      if (!r.latitude || !r.longitude) return false;
      const dist = distanciaEmKm(
        center.lat,
        center.lng,
        parseFloat(r.latitude),
        parseFloat(r.longitude)
      );
      return dist <= 5; // só revendas num raio de 5km
    });
    setFilteredRevendas(results);
  }

  // Enquanto atualiza dados
  if (loading) {
    return (
      <div
        style={{
          height: "100vh",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          background: "#f9f9f9",
        }}
      >
        <h2>🔄 Carregando dados da ANP...</h2>
        <p>{meta.progresso}% concluído</p>
        <div
          style={{
            width: "60%",
            background: "#ddd",
            borderRadius: "10px",
            overflow: "hidden",
            marginTop: "10px",
          }}
        >
          <div
            style={{
              width: `${meta.progresso}%`,
              height: "15px",
              background: "#4caf50",
              transition: "width 0.5s",
            }}
          />
        </div>
      </div>
    );
  }

  // Depois do carregamento
  return (
    <div style={{ height: "100vh", width: "100%", position: "relative" }}>
      {/* Última atualização */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          background: "white",
          padding: "8px 12px",
          borderRadius: "8px",
          boxShadow: "0px 2px 6px rgba(0,0,0,0.2)",
          zIndex: 1000,
        }}
      >
        <p style={{ margin: 0, fontSize: "12px" }}>
          Última atualização:{" "}
          {meta.ultimaAtualizacao
            ? new Date(meta.ultimaAtualizacao).toLocaleString("pt-PT")
            : "N/A"}
        </p>
      </div>

      {/* Filtros */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          background: "white",
          padding: "10px",
          borderRadius: "8px",
          boxShadow: "0px 2px 6px rgba(0,0,0,0.2)",
          zIndex: 1000,
        }}
      >
        <div>
          <label>UF: </label>
          <select
            value={selectedUf}
            onChange={(e) => {
              setSelectedUf(e.target.value);
              setSelectedMunicipio("");
            }}
          >
            <option value="">Todos</option>
            {ufs.map((uf) => (
              <option key={uf} value={uf}>
                {uf}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label>Município: </label>
          <select
            value={selectedMunicipio}
            onChange={(e) => setSelectedMunicipio(e.target.value)}
            disabled={!selectedUf}
          >
            <option value="">Todos</option>
            {municipios.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label>CNPJ: </label>
          <input
            type="text"
            value={cnpj}
            placeholder="Digite o CNPJ"
            onChange={(e) => setCnpj(e.target.value)}
          />
        </div>
      </div>

      <MapContainer
        center={userPosition || [-23.55, -46.63]} // São Paulo fallback
        zoom={6}
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer
          attribution="&copy; OpenStreetMap"
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* Captura eventos do mapa */}
        <MapaEventos onBoundsChange={handleBoundsChange} />

        {/* Posição do utilizador */}
        {userPosition && (
          <Marker position={userPosition}>
            <Popup>📍 Você está aqui</Popup>
          </Marker>
        )}

        {/* Revendas visíveis */}
        {filteredRevendas
          .filter((r) => r.latitude && r.longitude)
          .map((r, idx) => (
            <Marker
              key={idx}
              position={[parseFloat(r.latitude), parseFloat(r.longitude)]}
            >
              <Popup>
                <b>{r.razao_social}</b> <br />
                {r.rua}, {r.bairro}, {r.municipio}/{r.uf} <br />
                CNPJ: {r.cnpj} <br />
                <a
                  href={`https://waze.com/ul?ll=${r.latitude},${r.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Waze
                </a>{" "}
                |{" "}
                <a
                  href={`https://www.google.com/maps?q=${r.latitude},${r.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Maps
                </a>
              </Popup>
            </Marker>
          ))}
      </MapContainer>
    </div>
  );
}

export default MapView;
